1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export interface QuoteStep {
11	  op: "quote";
12	  items: Item[];
13	}
14	
15	export interface Item {
16	  type: string;
17	  material?: string;
18	  enchantment?: number;
19	  cursed?: boolean;
20	}
21	
22	export type Step = QuoteStep;
23	
24	export interface QuoteResult {
25	  premium: number;
26	}
27	
28	export type StepResult = QuoteResult;
29	
30	export interface ScenarioResult {
31	  results: StepResult[];
32	}
33	
34	const PROCESSING_FEE = 5;
35	
36	const FIRST_INSURANCE_SURCHARGE = 0.1;
37	
38	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
39	  sword: 100,
40	  amulet: 60,
41	  staff: 80,
42	};
43	
44	const basePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
45	
46	const quotePremium = (step: QuoteStep): number => {
47	  const policyBase = step.items.reduce(
48	    (sum, item) => sum + basePremium(item),
49	    0,
50	  );
51	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE;
52	  return policyBase + firstInsuranceSurcharge + PROCESSING_FEE;
53	};
54	
55	export const runScenario = (scenario: Scenario): ScenarioResult => ({
56	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
57	});
